package com.slss.domain;
import jakarta.persistence.*; import java.time.Instant;
@Entity @Table(name="refresh_tokens")
public class RefreshToken { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) Long id; @Column(name="token_hash",columnDefinition="CHAR(64)",nullable=false,unique=true) String tokenHash; @Column(nullable=false) String username; @Column(name="expires_at",nullable=false) Instant expiresAt; @Column(name="revoked_at") Instant revokedAt; @Column(name="created_at") Instant createdAt=Instant.now(); @Column(name="user_agent") String userAgent; @Column(name="ip_address") String ipAddress; public Long getId(){return id;} public String getTokenHash(){return tokenHash;} public String getUsername(){return username;} public Instant getExpiresAt(){return expiresAt;} public Instant getRevokedAt(){return revokedAt;} public Instant getCreatedAt(){return createdAt;} public String getUserAgent(){return userAgent;} public String getIpAddress(){return ipAddress;} public void setTokenHash(String v){tokenHash=v;} public void setUsername(String v){username=v;} public void setExpiresAt(Instant v){expiresAt=v;} public void setRevokedAt(Instant v){revokedAt=v;} public void setUserAgent(String v){userAgent=v;} public void setIpAddress(String v){ipAddress=v;} }
